SELECT mp.subject_id AS patient_id, AVG(mds.num_diagnoses) AS avg_diagnoses, SUM(CASE WHEN l.length_of_stay > 90 THEN 1 ELSE 0 END) AS mortality_after_90_days, SUM(CASE WHEN l.length_of_stay > 90 THEN 1 ELSE 0 END) / NULLIF(COUNT(l.subject_id), 0) AS proportion_of_patients_with_long_stay FROM male_patients mp JOIN male_admissions ma ON mp.subject_id = ma.subject_id JOIN male_diagnoses mds ON ma.subject_id = mds.subject_id JOIN male_los l ON ma.subject_id = l.subject_id WHERE age(CURRENT_DATE, to_date(mp.anchor_year, 'YYYY')) >= 68 GROUP BY mp.subject_id;